export type MemoryTranslator = (source: string, values?: Record<string, string | number>) => string;

/** Match authored templates only. Names and platform diagnostics remain data. */
export function localizeMemoryMessage(source: string, t: MemoryTranslator): string {
    const clearing = "Clearing could not finish; some entries may already be removed. Refresh and retry. ";
    if (source.startsWith(clearing)) return t("Clearing could not finish; some entries may already be removed. Refresh and retry. {detail}", { detail: localizeMemoryMessage(source.slice(clearing.length), t) });
    const recovery = ["Some previous values could not be restored; verify your records and use a backup.", "Previous values were restored."];
    for (const text of recovery) {
        const prefix = `Import could not finish. ${text} Check storage permissions/quota. `;
        if (source.startsWith(prefix)) return t("Import could not finish. {recovery} Check storage permissions/quota. {detail}", { recovery: t(text), detail: localizeMemoryMessage(source.slice(prefix.length), t) });
    }
    const timeout = /^Database ([\s\S]+) did not respond\.$/.exec(source);
    if (timeout) return t("Database {name} did not respond.", { name: timeout[1] });
    const permissions = /^Cannot read ([\s\S]+)\. Check browser storage permissions\.$/.exec(source);
    if (permissions) return t("Cannot read {name}. Check browser storage permissions.", { name: permissions[1] });
    const unreadable = /^Cannot read ([\s\S]+)\.$/.exec(source);
    if (unreadable) return t("Cannot read {name}.", { name: unreadable[1] });
    // Unrecognised browser diagnostics must not be interpreted as catalog keys.
    return Object.hasOwn(MEMORY_TRANSLATIONS, source) ? t(source) : source;
}

/** A fallback row label can be an arbitrary raw key or database/store name. */
export function memoryRowLabel(row: { engine: string; label: string; key: string; database?: string; toolId?: string }, t: MemoryTranslator): string {
    if (row.engine === "indexeddb" && row.toolId === "todo-list") return t("Tasks · {store}", { store: row.key });
    if (row.engine === "local" || row.engine === "session") {
        const baseKey = row.key.replace(/^mydevtools:project:[^:]+:/, "");
        if (row.label === baseKey) return row.label;
    }
    // Generic database/store labels consist entirely of source identifiers.
    if (row.database && row.label === `${row.database} · ${row.key}`) return row.label;
    return t(row.label);
}
